#!/usr/bin/env python3
"""Bundle all modules into ONE runnable file:  python make_single_file.py  ->  tactical8v8_single.py"""
import os

HERE = os.path.dirname(os.path.abspath(__file__))
ORDER = ["t8_data", "t8_textures", "t8_world", "t8_render", "t8_models", "t8_audio", "t8_entities", "t8_game",
         "t8_scene", "t8_ui"]


def main():
    out = ['#!/usr/bin/env python3',
           '"""TACTICAL 8v8 : ULTRA - single-file edition (generated by make_single_file.py).',
           'pip install pygame numpy arabic-reshaper python-bidi  &&  python tactical8v8_single.py"""',
           "import sys, types, os", "_SRC = {}"]
    for name in ORDER:
        src = open(os.path.join(HERE, name + ".py"), encoding="utf-8").read()
        out.append("_SRC[%r] = %r" % (name, src))
    out.append('''
for _name in %r:
    _m = types.ModuleType(_name)
    _m.__file__ = os.path.abspath(__file__)
    sys.modules[_name] = _m
    exec(compile(_SRC[_name], _name + ".py", "exec"), _m.__dict__)
''' % (ORDER,))
    main_src = open(os.path.join(HERE, "main.py"), encoding="utf-8").read()
    # the entry point is appended verbatim (its sys.path tweak is harmless)
    out.append(main_src)
    with open(os.path.join(HERE, "tactical8v8_single.py"), "w", encoding="utf-8") as f:
        f.write("\n".join(out))
    print("written tactical8v8_single.py")


if __name__ == "__main__":
    main()
